def pinned_requirements(lines):
    result = {}
    for line in lines:
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        parts = line.split("==")
        if len(parts) != 2 or not parts[0].strip() or not parts[1].strip():
            raise ValueError("Expected name==version")
        result[parts[0].strip()] = parts[1].strip()
    return result

