import json

def parse_documents(raw):
    records=json.loads(raw)
    if not isinstance(records,list):
        raise ValueError("Expected a list")
    result=[]
    for record in records:
        if not isinstance(record,dict):
            raise ValueError("Expected document objects")
        identifier=record.get("id")
        text=record.get("text")
        if not isinstance(identifier,str) or not identifier.strip() or not isinstance(text,str):
            raise ValueError("Invalid document")
        result.append({"id":identifier.strip(),"text":text})
    return result

def clean_documents(records):
    result=[]
    seen=set()
    for record in records:
        text=" ".join(record["text"].split())
        identifier=record["id"]
        if text and identifier not in seen:
            seen.add(identifier)
            result.append({"id":identifier,"text":text})
    return result

def process_export(raw):
    documents=clean_documents(parse_documents(raw))
    enriched=[{**doc,"word_count":len(doc["text"].split())} for doc in documents]
    return json.dumps({"documents":enriched,"document_count":len(enriched),"total_words":sum(doc["word_count"] for doc in enriched)})

